using System;
using System.IO;
using System.Windows;
using System.Windows.Media.Imaging;
using System.Windows.Controls;

namespace Login
{
    public partial class MainWindow : Window
    {
        public MainWindow()
        {
            InitializeComponent();
            CargarLogo();
        }

        // Carga el logo desde el texto Base64 de abajo (no necesita archivo de imagen)
        private void CargarLogo()
        {
            var bmp = new BitmapImage();
            using (var ms = new MemoryStream(Convert.FromBase64String(LogoBase64)))
            {
                bmp.BeginInit();
                bmp.CacheOption = BitmapCacheOption.OnLoad;
                bmp.StreamSource = ms;
                bmp.EndInit();
            }
            bmp.Freeze();
            ImgLogo.Source = bmp;
        }

        // Muestra el texto de ayuda de la contraseña solo si está vacía
        private void ActualizarHintPass()
        {
            if (TxtPassHint == null || BtnOjo == null) return;

            string actual = BtnOjo.IsChecked == true ? TxtPassVisible.Text : TxtPass.Password;
            TxtPassHint.Visibility = actual.Length == 0 ? Visibility.Visible : Visibility.Collapsed;
        }

        private void TxtPass_PasswordChanged(object sender, RoutedEventArgs e) => ActualizarHintPass();

        private void TxtPassVisible_TextChanged(object sender, TextChangedEventArgs e) => ActualizarHintPass();

        // Ojo: muestra u oculta la contraseña
        private void BtnOjo_Click(object sender, RoutedEventArgs e)
        {
            if (BtnOjo.IsChecked == true)
            {
                TxtPassVisible.Text = TxtPass.Password;
                TxtPass.Visibility = Visibility.Collapsed;
                TxtPassVisible.Visibility = Visibility.Visible;
                BtnOjo.Content = "\uED1A"; // ojo tachado
                TxtPassVisible.Focus();
                TxtPassVisible.CaretIndex = TxtPassVisible.Text.Length;
            }
            else
            {
                TxtPass.Password = TxtPassVisible.Text;
                TxtPassVisible.Visibility = Visibility.Collapsed;
                TxtPass.Visibility = Visibility.Visible;
                BtnOjo.Content = "\uE7B3"; // ojo
                TxtPass.Focus();
            }
            ActualizarHintPass();
        }

        private void BtnLogin_Click(object sender, RoutedEventArgs e)
        {
            string codigo = TxtCodigo.Text.Trim();
            string pass = BtnOjo.IsChecked == true ? TxtPassVisible.Text : TxtPass.Password;

            if (codigo.Length == 0)
            {
                TxtError.Text = "Introduce tu código.";
                TxtCodigo.Focus();
                return;
            }

            if (pass.Length < 4)
            {
                TxtError.Text = "La contraseña debe tener al menos 4 caracteres.";
                TxtPass.Focus();
                return;
            }

            TxtError.Text = "";

            // TODO: aquí comprueba el usuario contra tu base de datos / API.
            // Si es correcto, abre la ventana siguiente:
            // var detalles = new DetallesUsuarios();
            // detalles.Show();
            // this.Close();

            MessageBox.Show("Datos correctos. Conecta aquí tu autenticación.", "Login");
        }

        private const string LogoBase64 =
            "";
    }
}